# erection — the pillar of cloud at the door (Exodus 33:9-10 — 31:15's seat among the six), stiff-necked (32:9 — the six seats), the three books (32:32-33 — 29:19's blotting)
ER_PILLAR = ER.presence('pillar_face'); ER_STIFF = ER.calf('saru_stiff'); ER_BOOKS = ER.calf('three_books')
assert ER_PILLAR['v'] == (6, 5) and "'Deut 31:15'" in ER_PILLAR['why'] and ER_STIFF['v'] == (3, 6) and "'Deut 9:13'" in ER_STIFF['why'] and ER_BOOKS['v'] == ('wicked', 'righteous', 'middling'), (Q(ER_PILLAR)[:2], Q(ER_STIFF)[:2], Q(ER_BOOKS)[:2])
# beha — the seven clouds (Numbers 10:34 — the cloud's DATA on the kin; 12:5 the cloud at the door)
BH_CLOUDS = DD(BH)['seven_clouds']; assert BH_CLOUDS['value'] == 7 and BH_CLOUDS['settings']['7'].startswith('Sifrei 83:1'), BH_CLOUDS
BH_SUMMONS = BH.miriam({'ask': 'summons'}, DD(BH)); assert BH_SUMMONS[0] not in ('', 'no verdict in span'), BH_SUMMONS[0][:80]   # the live edge — Numbers 12:4's summons of the three to the tent (31:14's 'present yourselves' the kin)
# chukat — the death dates (Moses the seventh of Adar — THE MARKER'S DAY on the kin), the succession, the thirty days, the refrain born at 21:35 (31:4), Og's lore, the well's song, the three gifts by merit
CK_DATES = A(CK, 'edom_and_hor', 'death_dates'); CK_SUCC = A(CK, 'edom_and_hor', 'succession'); CK_30 = A(CK, 'edom_and_hor', 'thirty_days'); CK_REFRAIN = A(CK, 'well_and_kings', 'joshua_refrain'); CK_OG = A(CK, 'well_and_kings', 'og_lore'); CK_SANG = A(CK, 'well_and_kings', 'then_sang'); CK_WELL = DD(CK)['well_by_merit']
assert CK_DATES[0] == 'Aaron (40, 5, 1) by the ink, aged 123; Miriam the tenth of Nisan by the shelf; Moses the seventh of Adar (33:38-39; Seder Olam 10:2)' and 'invested_office' in CK_SUCC[1] and CK_30[0].startswith("thirty days' weeping by all the house of Israel — a timer due (40, 6, 1) (20:29; Deut 34:8 Moses' thirty)"), (CK_DATES[0], CK_SUCC[1], CK_30[0][:60])
assert CK_REFRAIN[1] == ['kings_smitten'] and CK_REFRAIN[0].startswith('"until no survivor was left" — born at 21:35') and CK_OG[1] == ['fear_not_promised'] and CK_SANG[1] == ['well_given'] and CK_WELL['value'] == 'miriams_gone_at_her_death_returned', (CK_REFRAIN[:2], CK_OG[1], CK_SANG[1], CK_WELL['value'])
# journeys — the four writings (31:9, 31:22 the second and the fourth), Aaron's death date the eras' stamp
JR_FOUR = DD(JR)['the_four_writings']; JR_DEATH = DD(JR)['the_death_date']
JR_WROTE = JR.the_heading_and_the_writing({'ask': 'moses_wrote'}, DD(JR)); assert JR_WROTE[0] not in ('', 'no verdict in span'), JR_WROTE[0][:80]   # the live edge — 33:2's 'and Moses wrote' (the four writings' cell)
assert JR_FOUR['value'] == ['Exod 24:4', 'Num 33:2', 'Deut 31:9', 'Deut 31:22'] and JR_DEATH['value'] == (40, 5, 1), (JR_FOUR['value'], JR_DEATH['value'])
# vestments — the Urim (Numbers 27:21 the first commission's judgment), its end with the first prophets
VE_URIM = VE.breastplate('urim'); VE_END = VE.breastplate('urim_end')
assert VE_URIM['v'] == (_G('האורים (the Urim)'), _G('התמים (the Tummim)')) and "'Num 27:21'" in VE_URIM['why'] and VE_END['v'] == 'first_prophets', (Q(VE_URIM)[:2], Q(VE_END)[:2])
# shelach (SHL — SH is the shared-run measure) — Hoshea to Joshua (Numbers 13:16; the old name at 32:44 — the same man)
SH_NAME = A(SHL, 'spies', 'joshua_name'); assert SH_NAME[0].startswith('Hoshea to Joshua at 13:16 — the new name at 8 seats before it, the old at Deut 32:44 (the same man)'), SH_NAME[0][:80]
# place_name — the place which He shall choose (31:11 — the stations' six rows; the three commandments of the entry)
PN_SIX = A(PN, 'the_place_chosen', 'the_stations_six_rows'); PN_THREE = A(PN, 'the_place_chosen', 'the_three_commandments_of_the_entry')
assert PN_SIX[0].startswith("the stations' six rows (12:9-11) — the wilderness permitted / forbidden under the Tabernacle, Gilgal permitted, Shiloh") and PN_THREE[0].startswith('the three commandments of the entry (12:10-11) — a king, Amalek, the chosen House, in order'), (PN_SIX[0][:60], PN_THREE[0][:60])
print("THE CALLEES' FACTS held: opening_speech, gad_reuben, good_land, exodus_story, covenant_at_horeb, hear_o_israel, seven_nations, obey_horeb, second_tablets, not_righteousness, blessing_and_curse, seducers, food_tithe, release_firstborn, festivals_judges, courts_prophet, firstfruits_ebal_curses, refuge_war_family, tochacha, yovel, calendar, moadim, musafim, mamre, primeval, family, erection, beha, chukat, journeys, vestments, shelach, place_name — thirty-three runners, every edge live at its cell")
